O que o script imprime?

```javascript
function criarReserva(estoque) {
  let restante = estoque;
  return (qtd) => {
    if (qtd > restante) return false;
    restante -= qtd;
    return true;
  };
}

const reservarLuminaria = criarReserva(2);
const reservarFone = criarReserva(8);
console.log(reservarLuminaria(1), reservarLuminaria(2));
